begin;
do $$
declare own_uid uuid; a public.ffh_profiles; b public.ffh_profiles; c public.ffh_profiles; fid uuid; nid uuid; tid bigint; found_count int; denied boolean;
begin
 select auth_user_id into own_uid from public.ffh_profiles where staff_id='M21954';
 select * into a from public.ffh_profiles where active and login_approved and role='SR' and auth_user_id is not null order by staff_id limit 1;
 select * into b from public.ffh_profiles where active and login_approved and role='SR' and auth_user_id is not null and staff_id<>a.staff_id order by staff_id limit 1;
 select * into c from public.ffh_profiles where active and login_approved and role='SR' and auth_user_id is not null and staff_id not in (a.staff_id,b.staff_id) order by staff_id limit 1;
 if own_uid is null or c.staff_id is null then raise exception 'Need owner and three active SR accounts to verify isolation';end if;
 perform set_config('request.jwt.claim.sub',own_uid::text,true);perform set_config('role','authenticated',true);
 fid:=public.ffh_save_finding(jsonb_build_object('kind','competitor','title','QA rollback product finding','category','Beverages','details',jsonb_build_object('wholesale_price',2.5,'retail_price',3.5,'description','Transactional test; not retained'),'recipients',jsonb_build_array(a.staff_id)));
 if (select states->a.staff_id->>'status' from public.ffh_findings where id=fid)<>'Pending' then raise exception 'Assignment must start pending';end if;
 perform set_config('request.jwt.claim.sub',a.auth_user_id::text,true);
 perform public.ffh_finding_receipt(fid,false);
 if (select states->a.staff_id->>'status' from public.ffh_findings where id=fid)<>'Pending' then raise exception 'Reading must not complete follow-up';end if;
 if (select states->a.staff_id->>'read_at' from public.ffh_findings where id=fid) is null then raise exception 'Read receipt missing';end if;
 perform public.ffh_finding_receipt(fid,true);
 if (select states->a.staff_id->>'status' from public.ffh_findings where id=fid)<>'Done' then raise exception 'Explicit completion failed';end if;
 perform set_config('request.jwt.claim.sub',b.auth_user_id::text,true);
 select count(*) into found_count from public.ffh_findings where id=fid;
 if found_count<>0 then raise exception 'Unassigned SR could read finding';end if;
 denied:=false;begin perform public.ffh_finding_receipt(fid,true);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Unassigned SR could complete a finding';end if;
 insert into public.ffh_private_notebook(owner_staff_id,note_date,folder,title,notes) values(b.staff_id,current_date,'QA rollback','QA disposable note','Transactional test') returning id into nid;
 delete from public.ffh_private_notebook where id=nid;
 select (value->>'id')::bigint into tid from jsonb_array_elements(public.ffh_owned_bin('list','ffh_private_notebook')) where value->'row_key'->>'id'=nid::text;
 if tid is null then raise exception 'Deleted note missing from durable Trash';end if;
 perform public.ffh_owned_bin('restore','ffh_private_notebook',tid);
 if not exists(select 1 from public.ffh_private_notebook where id=nid) then raise exception 'Undo did not restore note';end if;
 delete from public.ffh_private_notebook where id=nid;
 select (value->>'id')::bigint into tid from jsonb_array_elements(public.ffh_owned_bin('list','ffh_private_notebook')) where value->'row_key'->>'id'=nid::text;
 perform public.ffh_owned_bin('purge','ffh_private_notebook',tid);
 if exists(select 1 from jsonb_array_elements(public.ffh_owned_bin('list','ffh_private_notebook')) where value->>'id'=tid::text) then raise exception 'Purged test note remained in Trash';end if;
 perform set_config('request.jwt.claim.sub',c.auth_user_id::text,true);
 denied:=false;begin perform public.ffh_owned_bin('restore','ffh_private_notebook',tid);exception when insufficient_privilege then denied:=true;end;
 if not denied then raise exception 'Another SR could restore a private note';end if;
 perform set_config('request.jwt.claim.sub',own_uid::text,true);
 delete from public.ffh_findings where id=fid;
 select (value->>'id')::bigint into tid from jsonb_array_elements(public.ffh_owned_bin('list','ffh_findings')) where value->'row_key'->>'id'=fid::text;
 if tid is null then raise exception 'Finding missing from Trash';end if;
 perform public.ffh_owned_bin('restore','ffh_findings',tid);
 if (select states->a.staff_id->>'status' from public.ffh_findings where id=fid)<>'Done' then raise exception 'Restore lost reviewer progress';end if;
 perform set_config('role','postgres',true);
end $$;
rollback;
